window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2e03d8b874953156"]={"versions": [{"id": "FIG-2e03d8b874953156", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm im Rahmen <code>act Calculate DeltaCounter</code>. Das Diagramm beschreibt einen internen Berechnungsalgorithmus innerhalb des Moduls E2E (End-to-End Communication Protection Library) der AUTOSAR Classic Platform zur Ermittlung des Zählerdifferenzwerts (<code>DeltaCounter</code>) zwischen empfangenem und zuletzt gültigem Zählerstand eines E2E-Profils (Profil 1 mit Zählerbereich 0–15).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Startknoten (Initial Node) mit Beschriftung <code>Calculate DeltaCounter</code></li>\n<li>Zuweisungs- bzw. Aktionsknoten: <code>DeltaCounter = ReceivedCounter - State-&gt;LastValidCounter</code> und <code>DeltaCounter = DeltaCounter + 16</code></li>\n<li>Entscheidungsknoten (Decision Node) mit Verzweigungsbedingung <code>(sint8) DeltaCounter &lt; 0 ?</code> und Guards <code>[TRUE]</code> sowie <code>[FALSE]</code></li>\n<li>Zusammenführungsknoten (Merge Node)</li>\n<li>Endknoten (Activity Final Node) mit Beschriftung <code>return</code></li>\n<li>Beteiligte Variablen und Attribute: <code>DeltaCounter</code>, <code>ReceivedCounter</code>, <code>State-&gt;LastValidCounter</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Ausgehend vom Startknoten wird im ersten Aktionsknoten die vorläufige Differenz gebildet: <code>DeltaCounter = ReceivedCounter - State-&gt;LastValidCounter</code>.</li>\n<li>Am Entscheidungsknoten wird geprüft, ob <code>(sint8) DeltaCounter &lt; 0</code> erfüllt ist (Erkennung eines Zählerüberlaufs bzw. Wrap-Arounds):</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ist die Bedingung <code>[TRUE]</code>, wird die Modulo-Korrektur <code>DeltaCounter = DeltaCounter + 16</code> ausgeführt.</li>\n<li>Ist die Bedingung <code>[FALSE]</code>, wird der Pfad ohne Anpassung fortgesetzt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Beide Steuerflusspfade laufen in einem Zusammenführungsknoten zusammen.</li>\n<li>Der Kontrollfluss erreicht den Aktivitätsendknoten (<code>return</code>), womit der berechnete <code>DeltaCounter</code> zur weiteren Validierung bereitsteht.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation definiert verbindlich die Berechnung der Zählerdifferenz für 4-Bit-Zähler (Wertebereich 0 bis 15). Ein Zählerüberlauf führt bei einfacher Subtraktion zu einem negativen vorzeichenbehafteten Ergebnis (<code>sint8</code>), welches durch Addition von 16 normiert werden muss. Entwickler müssen sicherstellen, dass <code>DeltaCounter</code> bei der Überprüfung vorzeichenbehaftet interpretiert wird (<code>(sint8)</code>), um Fehleinschätzungen des Abstands zu verhindern.</p>"}, {"id": "FIG-4e43f59997154296", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm ohne äußeren Rahmen. Das Diagramm beschreibt einen internen Berechnungsalgorithmus innerhalb des Moduls E2E (End-to-End Communication Protection Library) der AUTOSAR Classic Platform zur Ermittlung des Zählerdifferenzwerts (<code>DeltaCounter</code>) zwischen empfangenem und zuletzt gültigem Zählerstand eines E2E-Profils (Profil 1 mit Zählerbereich 0–15).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Startknoten (Initial Node)</li>\n<li>Zuweisungs- bzw. Aktionsknoten: <code>DeltaCounter = ReceivedCounter - State-&gt;LastValidCounter</code> und <code>DeltaCounter = DeltaCounter + 16</code></li>\n<li>Entscheidungsknoten (Decision Node) mit Verzweigungsbedingung <code>(sint8) DeltaCounter &lt; 0 ?</code> und Guards <code>[TRUE]</code> sowie <code>[FALSE]</code></li>\n<li>Zusammenführungsknoten (Merge Node)</li>\n<li>Endknoten (Activity Final Node)</li>\n<li>Beteiligte Variablen und Attribute: <code>DeltaCounter</code>, <code>ReceivedCounter</code>, <code>State-&gt;LastValidCounter</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Ausgehend vom Startknoten wird im ersten Aktionsknoten die vorläufige Differenz gebildet: <code>DeltaCounter = ReceivedCounter - State-&gt;LastValidCounter</code>.</li>\n<li>Am Entscheidungsknoten wird geprüft, ob <code>(sint8) DeltaCounter &lt; 0</code> erfüllt ist (Erkennung eines Zählerüberlaufs bzw. Wrap-Arounds):</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ist die Bedingung <code>[TRUE]</code>, wird die Modulo-Korrektur <code>DeltaCounter = DeltaCounter + 16</code> ausgeführt.</li>\n<li>Ist die Bedingung <code>[FALSE]</code>, wird der Pfad ohne Anpassung fortgesetzt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Beide Steuerflusspfade laufen in einem Zusammenführungsknoten zusammen.</li>\n<li>Der Kontrollfluss erreicht den Aktivitätsendknoten, womit der berechnete <code>DeltaCounter</code> zur weiteren Validierung bereitsteht.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation definiert verbindlich die Berechnung der Zählerdifferenz für 4-Bit-Zähler (Wertebereich 0 bis 15). Ein Zählerüberlauf führt bei einfacher Subtraktion zu einem negativen vorzeichenbehafteten Ergebnis (<code>sint8</code>), welches durch Addition von 16 normiert werden muss. Entwickler müssen sicherstellen, dass <code>DeltaCounter</code> bei der Überprüfung vorzeichenbehaftet interpretiert wird (<code>(sint8)</code>), um Fehleinschätzungen des Abstands zu verhindern.</p>"}], "trans": [{"from": "FIG-2e03d8b874953156", "to": "FIG-4e43f59997154296", "fr": "R3.2.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Der äußere UML-Aktivitätsrahmen (<code>act Calculate DeltaCounter</code>) sowie die redundante Titelbeschriftung oberhalb des Startknotens (<code>Calculate DeltaCounter</code>) wurden entfernt.</li>\n<li>Die Textbeschriftung <code>return</code> am Aktivitätsendknoten wurde entfernt.</li>\n<li>Die inhaltliche Ablauflogik, Knoten und Kanten sind unverändert.</li>\n</ul>"}]};
